+// Till sales: each dish sold uses one portion of its recipe per qty. A ticket
+// is imported once; importing a set of sales is all or nothing.
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a sale with this ticket was already imported. */
+export function ticketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sales rows { row, ticket, soldAt, dishId, qty } and consumes their
+ * ingredients (ref "sale:<ticket>"). Tickets already imported are skipped.
+ * Returns { tickets, dishes } counts; throws (changing nothing) naming the row.
+ */
+export function recordSales(store, rows) {
+  const fresh = rows.filter((r) => !ticketImported(store, r.ticket));
+  const planned = fresh.map((r) => {
+    const dish = getDish(store, r.dishId);
+    return { ...r, uses: scaled(getRecipe(store, dish.recipeId), r.qty) };
+  });
+  const need = new Map();
+  for (const p of planned) {
+    for (const u of p.uses) {
+      const item = getItem(store, u.itemId);
+      const total = round3((need.get(u.itemId) ?? 0) + u.qty);
+      const available = round3(onHand(store, u.itemId));
+      if (available < total)
+        throw new AppError("sale_out_of_stock", { row: p.row, item: item.name, available, unit: item.unit });
+      need.set(u.itemId, total);
+    }
+  }
+  const backup = structuredClone(store.data);
+  try {
+    store.data.sales ??= [];
+    for (const p of planned) {
+      for (const u of p.uses) if (u.qty > 0) consume(store, u.itemId, u.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+      store.data.sales.push({ id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, uses: p.uses });
+    }
+  } catch (e) {
+    store.data = backup;
+    throw e;
+  }
+  return { tickets: new Set(planned.map((p) => p.ticket)).size, dishes: planned.reduce((s, p) => s + p.qty, 0) };
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * against actual use (every consume movement), for items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    for (const u of s.uses) theoretical.set(u.itemId, round3((theoretical.get(u.itemId) ?? 0) + u.qty));
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, round3((actual.get(batch.itemId) ?? 0) + m.qty));
+  }
+  return [...new Set([...theoretical.keys(), ...actual.keys()])]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = theoretical.get(itemId) ?? 0;
+      const a = actual.get(itemId) ?? 0;
+      return { itemId, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
